import { test, expect } from '@playwright/test';

test.describe('File Upload Retry Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload'); // Replace with the actual upload page URL
  });

  test('should upload a file successfully', async ({ page }) => {
    const filePath = 'path/to/valid/file.txt'; // Replace with the actual file path
    await page.getByLabel('File Upload').setInputFiles(filePath);
    await page.getByRole('button', { name: 'Upload' }).click();
    await expect(page.getByText('Upload successful')).toBeVisible();
  });

  test('should retry a failed upload without re-selecting the file', async ({ page }) => {
    const filePath = 'path/to/invalid/file.txt'; // Replace with the actual invalid file path
    await page.getByLabel('File Upload').setInputFiles(filePath);
    await page.getByRole('button', { name: 'Upload' }).click();
    await expect(page.getByText('Upload failed')).toBeVisible();

    await page.getByRole('button', { name: 'Retry' }).click();
    await expect(page.getByText('Upload successful')).toBeVisible();
  });
});
